//! Complete 6-language localization catalog for DataForge UI strings.
//!
//! Supported languages:
//! - English (`en-US`)
//! - Tiếng Việt (`vi-VN`)
//! - 简体中文 (`zh-CN`)
//! - 日本語 (`ja-JP`)
//! - Español (`es-ES`)
//! - Français (`fr-FR`)

use dataforge_services::diagnostics::LocaleTable;

/// Supported UI locales in DataForge.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Locale {
    /// English (United States) — default.
    #[default]
    EnUs,
    /// Vietnamese (`vi-VN`).
    ViVn,
    /// Simplified Chinese (`zh-CN`).
    ZhCn,
    /// Japanese (`ja-JP`).
    JaJp,
    /// Spanish (`es-ES`).
    EsEs,
    /// French (`fr-FR`).
    FrFr,
}

impl Locale {
    /// All supported UI locales in display order.
    pub const ALL: [Self; 6] = [
        Self::EnUs,
        Self::ViVn,
        Self::ZhCn,
        Self::JaJp,
        Self::EsEs,
        Self::FrFr,
    ];

    /// Canonical BCP-47 language tag.
    #[must_use]
    pub const fn code(self) -> &'static str {
        match self {
            Self::EnUs => "en-US",
            Self::ViVn => "vi-VN",
            Self::ZhCn => "zh-CN",
            Self::JaJp => "ja-JP",
            Self::EsEs => "es-ES",
            Self::FrFr => "fr-FR",
        }
    }

    /// Native endonym displayed inside Settings language pickers.
    #[must_use]
    pub const fn native_name(self) -> &'static str {
        match self {
            Self::EnUs => "English (en-US)",
            Self::ViVn => "Tiếng Việt (vi-VN)",
            Self::ZhCn => "简体中文 (zh-CN)",
            Self::JaJp => "日本語 (ja-JP)",
            Self::EsEs => "Español (es-ES)",
            Self::FrFr => "Français (fr-FR)",
        }
    }

    /// Parses a BCP-47 or POSIX locale string (e.g. `"vi_VN.UTF-8"`, `"zh"`, `"ja-JP"`).
    #[must_use]
    pub fn from_code(raw: &str) -> Option<Self> {
        let normalized = raw.trim().to_ascii_lowercase().replace('_', "-");
        if normalized.is_empty() {
            return None;
        }
        if normalized.starts_with("en") {
            Some(Self::EnUs)
        } else if normalized.starts_with("vi") {
            Some(Self::ViVn)
        } else if normalized.starts_with("zh") {
            Some(Self::ZhCn)
        } else if normalized.starts_with("ja") {
            Some(Self::JaJp)
        } else if normalized.starts_with("es") {
            Some(Self::EsEs)
        } else if normalized.starts_with("fr") {
            Some(Self::FrFr)
        } else {
            None
        }
    }
}

