impl Strings {
    /// Returns the complete string catalog for `locale`.
    #[must_use]
    pub const fn for_locale(locale: Locale) -> Self {
        match locale {
            Locale::EnUs => EN_US,
            Locale::ViVn => VI_VN,
            Locale::ZhCn => ZH_CN,
            Locale::JaJp => JA_JP,
            Locale::EsEs => ES_ES,
            Locale::FrFr => FR_FR,
        }
    }
}

